                $domain['outcomes'] = $localized['domain_outcomes'];
                $domain['signals'] = $localized['domain_signals'];
            }
            $domain['industries'] = $industryMap[$slug];
            $domain['industry_labels'] = array_map(static fn(string $key): string => $industryLabels[$key], $domain['industries']);
            $domain['problem'] = sprintf($detail['problem_template'], $domain['title']);
            $domain['scenario'] = [
                sprintf($detail['scenario_event'], $domain['signals'][0]),
                $detail['scenario_decision'],
                sprintf($detail['scenario_action'], $domain['outcomes'][0]),
                $detail['scenario_result'],
            ];
