                'exception-management'=>['headline'=>'Нормальний процес працює тихо. Відхилення запускає дію.','promise'=>'Exception Management контролює очікуваний хід процесу, автоматично виправляє прості відхилення й залучає людину лише там, де потрібні судження, погодження або відповідальність.','problem'=>'Звичайний дашборд показує вчорашнє відхилення. COS бачить його, поки результат ще можна врятувати, обирає реакцію та не знімає контроль до підтвердження результату.','pillars'=>['Модель нормального процесу, допусків і критичних меж','Автоматичне виправлення, повторна спроба або безпечна зупинка','Ескалація людині разом із контекстом і варіантами рішення','Аналіз повторюваних проблем та зміна правила процесу'],'scenarios'=>['Прострочено обіцяний follow-up і угода ризикує зірватися','Затримка постачальника загрожує виробництву або доставці','Критичне порушення політики зупиняє процес до появи збитків']],
                'executive-control'=>['headline'=>'Увага керівника спрямована лише на те, що змінює результат.','promise'=>'Executive Control замінює інформаційний шум щоденною картиною відхилень, ранжованими пріоритетами, відповідальними рішеннями та перевіркою фактичного ефекту.','problem'=>'Керівникам зазвичай не бракує звітів. Їм бракує надійної відповіді на чотири питання: що змінилося, чому це важливо, хто має діяти і чи спрацювало рішення.','pillars'=>['Щоденний дайджест відхилень і управлінських пріоритетів','План-факт із поясненням причин, а не лише цифрами','Журнал рішень, відповідальних і контрольних строків','Прогнози, сценарії та перевірка фактичного результату'],'scenarios'=>['Прогноз місяця погіршується до того, як втрату вже неможливо компенсувати','Затримки між відділами показують системне вузьке місце','Рішення керівника контролюється від доручення до виміряного ефекту']],
                'sales'=>['headline'=>'Жоден лід не чекає. Жодна угода не залишається без наступного кроку.','promise'=>'COS Sales перетворює кожен лід, дзвінок, лист і зміну в угоді на своєчасну комерційну дію. Керівник отримує достовірну воронку, а продавці витрачають більше часу на клієнтів.','problem'=>'Виручка втрачається через повільну першу відповідь, пропущені дзвінки, забуті follow-up, обіцянки в листуванні та угоди без реального наступного кроку. Дашборд показує втрату постфактум; COS діє, поки угоду ще можна виграти.','pillars'=>['Зібрати, збагатити, кваліфікувати й розподілити кожен лід','Визначити та запустити найкращу наступну дію для кожної угоди','Перетворити дзвінки й листування на контекст CRM, задачі та зобов’язання','Прогнозувати виручку, виявляти ризики та запускати продовження або upsell'],'scenarios'=>['Гарячий лід одразу отримує персональну відповідь і відповідального менеджера','COS знаходить завислу угоду до втрати інтересу покупця й готує наступний крок','Наближення продовження договору запускає аналіз клієнта та цільову пропозицію']],
                'operations'=>['headline'=>'Перетворіть кожне замовлення на контрольоване виконання.','promise'=>'COS Operations перетворює правила компанії на workflows, які координують команди й системи, захищають строки та усувають відхилення до того, як їх відчує клієнт.','problem'=>'Більшість операційних втрат виникає між відділами: замовлення вже є, але наступна задача запізнюється; одна команда завершила роботу, але передачу пропущено; усі зайняті, проте ніхто не відповідає за кінцевий результат. COS закриває ці розриви.','pillars'=>['Запустити правильний процес із кожної бізнес-події','Контролювати відповідальних, залежності, передачі та строки','Автоматично усувати типові винятки, а складні передавати людині з контекстом','Вимірювати операційний цикл, повторювані проблеми та справжні причини затримок'],'scenarios'=>['Підтверджене замовлення автоматично створює повний процес виконання з відповідальними та строками','Заблоковану передачу між відділами виправлено до порушення обіцянки клієнту','Повторювана помилка змінює правило процесу замість чергового ручного обходу']],
                'logistics'=>['headline'=>'Потрібний запас. Вчасна доставка. Менше дорогих несподіванок.','promise'=>'COS Inventory & Logistics поєднує попит, запаси, закупівлі, комплектацію та доставку, щоб попереджати дефіцит, вивільняти заморожений капітал і захищати кожну обіцянку клієнту.','problem'=>'Маржа зникає в надлишкових запасах, термінових закупівлях, пропущеному поповненні, дисбалансі складів і затримках доставки. Кожна система бачить фрагмент; COS контролює весь потік і діє до появи комерційної втрати.','pillars'=>['Прогнозувати попит і виявляти ризик дефіциту, надлишку або неліквіду','Координувати поповнення, розподіл, комплектацію та етапи відвантаження','Виявляти затримки доставки й проактивно інформувати клієнта','Контролювати повернення, партії, серійні номери, строки придатності та перевізників'],'scenarios'=>['Ризик дефіциту створює обґрунтовану пропозицію поповнення до втрати продажів','Затримка доставки запускає відновлювальні дії та проактивне повідомлення клієнту','Надлишковий запас виявлено й перерозподілено до заморожування оборотного капіталу']],
            ],
        ];

        $focus = [
            'de'=>['data-fabric'=>'Eine verlässliche gemeinsame Datenbasis ersetzt widersprüchliche Teilbilder.','exception-management'=>'Abweichungen lösen rechtzeitig eine kontrollierte Reaktion aus.','executive-control'=>'Führungskräfte sehen Prioritäten, Verantwortliche und geprüfte Wirkung statt Informationsrauschen.','sales'=>'Jeder Lead erhält rechtzeitig eine passende Aktion, während Pipeline-Risiken sichtbar werden, bevor Umsatz verloren geht.','operations'=>'Aufträge werden zu kontrollierten Abläufen mit klaren Verantwortlichen, Übergaben und messbaren Ergebnissen.','logistics'=>'Bestand, Nachfrage und Lieferung werden gemeinsam gesteuert, um Fehlmengen, gebundenes Kapital und Verspätungen zu reduzieren.'],
            'fr'=>['data-fabric'=>'Un contexte commun fiable remplace les vues partielles contradictoires.','exception-management'=>'Chaque écart déclenche à temps une réponse maîtrisée.','executive-control'=>'La direction voit les priorités, les responsables et l’effet vérifié plutôt que le bruit informationnel.','sales'=>'Chaque prospect reçoit la bonne action à temps et les risques du pipeline deviennent visibles avant la perte de chiffre d’affaires.','operations'=>'Chaque commande devient un processus maîtrisé avec responsables, transferts et résultats mesurables.','logistics'=>'Stocks, demande et livraison sont pilotés ensemble afin de réduire ruptures, capital immobilisé et retards.'],
            'pl'=>['data-fabric'=>'Jeden wiarygodny kontekst zastępuje sprzeczne obrazy z wielu systemów.','exception-management'=>'Każde odchylenie uruchamia na czas kontrolowaną reakcję.','executive-control'=>'Zarząd widzi priorytety, właścicieli i zweryfikowany efekt zamiast szumu informacyjnego.','sales'=>'Każdy lead otrzymuje właściwe działanie na czas, a ryzyka w lejku są widoczne przed utratą przychodu.','operations'=>'Każde zamówienie staje się kontrolowanym procesem z właścicielami, przekazaniami i mierzalnym wynikiem.','logistics'=>'Zapasy, popyt i dostawy są zarządzane wspólnie, aby ograniczyć braki, zamrożony kapitał i opóźnienia.'],
        ];
        foreach (['de','fr','pl'] as $lang) {
            $labels = $this->featuredLabels()[$lang];
            foreach (array_merge(self::FEATURED_DOMAINS, self::SPOTLIGHT_DOMAINS) as $slug) {
                $title = $this->domainTitles()[$lang][$slug];
                $presentations[$lang][$slug] = ['headline'=>sprintf($labels['headline_template'], $title),'promise'=>$focus[$lang][$slug],'problem'=>sprintf($labels['problem_template'], $focus[$lang][$slug]),'pillars'=>$labels['generic_pillars'],'scenarios'=>$labels['generic_scenarios']];
