    private function commonGroups(): array
    {
        return $this->localizedGroups(array_combine(['Control','Revenue','Experience','Execution','Supply','Industry','Organisation','Trust','Growth','Core'], ['Control','Revenue','Experience','Execution','Supply','Industry','Organisation','Trust','Growth','Core']));
